12	import ly.com.tahaben.notification_filter_domain.model.PriorityDeliverySetting
13	
14	enum class NotificationRemovalReason {
15	    /** The source app cancelled its notification: explicit, clears a queued row. */
16	    SOURCE_APP_CANCELLED,
17	
18	    /** The user swiped or tapped away a Farhan proxy: explicit. */
19	    USER_DISMISSED,
20	
21	    /** Farhan's own interception or snooze removal: not a cancellation. */
22	    FARHAN_INTERCEPTED,
23	
24	    /** The user opened the source app: not a cancellation by itself. */
25	    SOURCE_APP_OPENED,
26	    INBOX_CLEARED,
27	}
28	
29	sealed interface PostResult {
30	    data object Posted : PostResult
31	    data class Failed(val reason: String) : PostResult
32	}
33	
34	sealed interface DeliveryOutcome {
35	    val id: String
36	    data class Delivered(override val id: String) : DeliveryOutcome
37	    /** Stored and waiting: cadence not due, or no budget. */
38	    data class Deferred(override val id: String) : DeliveryOutcome
39	    /** Ambiguous callback history was evicted. The persisted row remains available in the inbox. */
40	    data class Invalidated(override val id: String) : DeliveryOutcome
41	    /** An explicit cancellation won: nothing posted, nothing spent. */
42	    data class Cleared(override val id: String) : DeliveryOutcome
43	    data class PostFailed(override val id: String, val reason: String) : DeliveryOutcome
44	    /** External effect succeeded; storage will be retried before another mutation, without reposting. */
45	    data class CommitPending(override val id: String) : DeliveryOutcome
46	}
47	
48	/** Row storage with Room semantics: [upsert] replaces every column, [markCleared] on a missing id does nothing. */
49	interface DeliveryRowStore {
50	    suspend fun upsert(item: NotificationItem)
51	    suspend fun find(id: String): NotificationItem?
52	    suspend fun markCleared(id: String)
53	    suspend fun markDelivered(id: String)
54	    suspend fun completeSnoozeReturn(id: String)
55	    suspend fun liveSnoozes(): List<NotificationItem> = emptyList()
56	    suspend fun pending(maxPriorityLevel: Int): List<NotificationItem>
57	    suspend fun invalidateBefore(session: String, order: Long)
58	    suspend fun nextHead(after: NotificationItem): NotificationItem? = null
59	}
60	
61	interface DeliveryBudgetStore {
62	    suspend fun read(): DeliveryBudgetState
63	    suspend fun write(state: DeliveryBudgetState)
64	    suspend fun appendSpend(entry: BudgetSpendEntry)
65	}
66	
67	/** Android-bound in production (NotificationManager). Must report failure, not hide it. */
68	interface ProxyNotificationPoster {
69	    suspend fun post(item: NotificationItem): PostResult
70	    suspend fun refresh(item: NotificationItem): PostResult = PostResult.Posted
71	}
72	
73	/** Reads of settings that can change between calls. */
74	interface DeliveryEnvironment {
75	    fun schedule(): List<NotificationSchedulePeriod>
76	    fun zone(): ZoneId = ZoneId.systemDefault()
77	    fun scheduleAt(instant: Instant, zone: ZoneId): List<NotificationSchedulePeriod>
78	    fun settings(): Map<NotificationPriority, PriorityDeliverySetting>
79	    fun timeContext(): DeliveryTimeContext
80	    fun queuePreferences(): Map<String, AppQueuePreference>
81	    fun activeSourceKeys(): Set<String> = emptySet()
82	}
83	
84	/**
85	 * One owner for authorization and spend. CLAIM(serialized-budget), CLAIM(post-failure-no-spend):
86	 * [NotificationDeliveryCoordinatorTest]. The injected gate is shared with ScheduleWriter.
87	 * Posting is an external effect; durable adapters must document their crash boundary.
88	 */
89	class NotificationDeliveryCoordinator(
90	    private val rows: DeliveryRowStore,
91	    private val budget: DeliveryBudgetStore,
92	    private val poster: ProxyNotificationPoster,
93	    private val environment: DeliveryEnvironment,
94	    private val gate: DeliveryGate = DeliveryGate(),
95	    private val eventCapacity: Int = MAX_EVENT_KEYS,
96	) {
97	    private data class Event(val order: Long, val removed: Boolean, val lastRemoval: Long, val accepted: Long, val bypassed: Boolean = false, val appliedRemoval: Long = 0)
98	    private val events = linkedMapOf<String, Event>()
99	    private val legacyRemovals = linkedMapOf<String, Long>()
100	    private var sequence = 0L
101	    private var discardedBefore = 0L
102	    private val sourceSession = java.util.UUID.randomUUID().toString()
103	    private var persistedInvalidation = 0L
104	    private data class Completion(val id: String, val state: DeliveryBudgetState, val entry: BudgetSpendEntry?,
105	        val nativeReturn: Boolean = false, var rowSaved: Boolean = false, var budgetSaved: Boolean = false)
106	    private var completion: Completion? = null
107	
108	    init { require(eventCapacity > 0); gate.recover = { finishCompletion(); persistInvalidations() } }
109	
110	    private suspend fun persistInvalidations() {
111	        val cutoff = synchronized(this) { discardedBefore }
112	        if (cutoff > persistedInvalidation) {
113	            rows.invalidateBefore(sourceSession, cutoff)
114	            persistedInvalidation = cutoff
115	        }
116	    }
117	    private fun ambiguous(item: NotificationItem): Boolean = synchronized(this) {
118	        item.sourceSession == sourceSession && item.sourceEventOrder > 0 && item.sourceEventOrder <= discardedBefore
119	    }
120	
121	    private suspend fun finishCompletion() {
122	        val pending = completion ?: return
123	        if (!pending.rowSaved) {
124	            if (pending.nativeReturn) rows.completeSnoozeReturn(pending.id) else rows.markDelivered(pending.id)
125	            pending.rowSaved = true
126	        }
127	        if (!pending.budgetSaved) { budget.write(pending.state); pending.budgetSaved = true }
128	        pending.entry?.let { budget.appendSpend(it) }
129	        completion = null
130	    }
131	
132	    @Synchronized private fun invalidateAll() { discardedBefore = ++sequence; events.clear() }
133	
134	
135	    /** Capture on the listener callback, before async discovery/classification. No private data is logged.
136	     * At capacity, conservatively refuse callbacks older than the evicted event, rather than resurrect them.
137	     */
138	    @Synchronized
139	    fun captureEvent(id: String, removed: Boolean = false, bypassed: Boolean = false): Long {
140	        val order = ++sequence
141	        val previous = events.remove(id)
142	        events[id] = Event(order, removed, if (removed) order else previous?.lastRemoval ?: 0, previous?.accepted ?: 0, bypassed, previous?.appliedRemoval ?: 0)
143	        if (events.size > eventCapacity) {
144	            val oldest = events.entries.first()
145	            discardedBefore = maxOf(discardedBefore, oldest.value.order)
146	            events.remove(oldest.key)
147	        }
148	        return order
149	    }
150	
151	    @Synchronized
152	    private fun stale(id: String, order: Long?, timestamp: Long): Boolean =
153	        if (order != null) order <= discardedBefore || events[id]?.let { it.order > order || it.removed } == true
154	        else (legacyRemovals[id] ?: Long.MIN_VALUE) >= timestamp
155	
156	    @Synchronized
157	    private fun explicitlyRemoved(id: String): Boolean = events[id]?.let { it.lastRemoval > it.accepted } == true
158	    @Synchronized private fun removalApplied(id: String, order: Long) {
159	        events[id]?.let { events[id] = it.copy(appliedRemoval = maxOf(it.appliedRemoval, order)) }
160	    }
161	    @Synchronized private fun bypassed(id: String): Boolean = events[id]?.bypassed == true
162	    @Synchronized private fun unprocessed(id: String): Boolean = events[id]?.let { it.order > it.accepted && !it.removed } == true
163	    @Synchronized private fun accept(id: String, order: Long?) {
164	        if (order != null) events[id]?.let { events[id] = it.copy(accepted = maxOf(it.accepted, order)) }
165	    }
166	
167	    suspend fun onArrival(
168	        item: NotificationItem,
169	        effectivePriority: NotificationPriority,
170	        eventOrder: Long? = null,
171	        passThrough: Boolean = false,
172	        captureActions: (() -> Unit)? = null,
173	        sourceStillCurrent: (() -> Boolean)? = null,
174	    ): DeliveryOutcome = gate.run {
175	        if (stale(item.id, eventOrder, item.timestamp)) return@run DeliveryOutcome.Cleared(item.id)
176	        if (sourceStillCurrent?.invoke() == false) return@run DeliveryOutcome.Deferred(item.id)
177	        val previous = rows.find(item.id)
178	        val delivered = previous?.isDelivered == true && !previous.isCleared && !explicitlyRemoved(item.id)
179	        val updated = item.copy(priority = effectivePriority, isRead = previous?.isRead ?: item.isRead,
180	            isDelivered = delivered || passThrough, isCleared = false, deliveryInvalidated = false,
181	            sourceSession = if (eventOrder != null) sourceSession else item.sourceSession,
182	            sourceEventOrder = eventOrder ?: item.sourceEventOrder)
183	        rows.upsert(updated)
184	        if (stale(item.id, eventOrder, item.timestamp)) { rows.markCleared(item.id); return@run DeliveryOutcome.Cleared(item.id) }
185	        accept(item.id, eventOrder)
186	        captureActions?.invoke()
187	        if (passThrough) return@run DeliveryOutcome.Delivered(item.id)
188	        if (delivered) {
189	            return@run when (val post = postSafely(updated, refresh = true)) {
190	                PostResult.Posted -> DeliveryOutcome.Delivered(item.id)
191	                is PostResult.Failed -> DeliveryOutcome.PostFailed(item.id, post.reason)
192	            }
193	        }
194	        val setting = environment.settings()[effectivePriority] ?: PriorityDeliverySetting.defaultFor(effectivePriority)
195	        if (!NotificationDeliveryPolicy.shouldDeliverOnArrival(setting)) return@run DeliveryOutcome.Deferred(item.id)
196	        if (stale(item.id, eventOrder, item.timestamp)) DeliveryOutcome.Cleared(item.id)
197	        else if (sourceStillCurrent?.invoke() == false) DeliveryOutcome.Deferred(item.id) else deliver(updated)
198	    }
199	
200	    // CLAIM(snooze-return-crash): may undercharge one return after a crash, never double charge [Snooze pilot spec W2].
201	    // The return row step, budget state and spend entry are committed in that order.
202	    suspend fun settleSnoozeReturn(key: String, postTime: Long, now: Instant): SnoozeReturnDecision = try {
203	        gate.run {
204	            val row = rows.find(key) ?: return@run SnoozeReturnDecision.NotOwned
205	            val priority = row.snoozePriority ?: return@run SnoozeReturnDecision.NotOwned
206	            if (!row.hasLiveSnooze) return@run SnoozeReturnDecision.NotOwned
207	            val time = environment.timeContext()
208	            val schedule = environment.schedule()
209	            val setting = environment.settings()[priority] ?: PriorityDeliverySetting.defaultFor(priority)
210	            val decision = NotificationDeliveryPolicy.canDeliverNow(priority, setting, schedule, time, budget.read())
211	            if (!decision.canDeliver) {
212	                val zone = environment.zone()
213	                val owned = rows.liveSnoozes().filterNot { it.id == key }
214	                val next = SnoozeTiming.nextDeliverableMoment(priority, setting, environment::scheduleAt, now, zone, time.testingMode) { tick, _, _ ->
215	                    hasSnoozeCapacity(priority, setting, decision.updatedBudget, owned, tick, zone, time.testingMode, environment.scheduleAt(tick, zone))
216	                }
217	                return@run next?.let(SnoozeReturnDecision::RetryAt) ?: SnoozeReturnDecision.NoFundedMoment
218	            }
219	            val charged = NotificationDeliveryPolicy.recordPassthrough(priority, setting, schedule, time.scheduleMinuteOfDay, decision.updatedBudget)
220	            val spend = if (setting.budgetBehavior == BudgetBehavior.RESPECTING && priority.pointCost > 0) {
221	                BudgetSpendEntry(row.appName.orEmpty(), row.title.orEmpty(), priority, priority.pointCost, now.toEpochMilli(),
222	                    charged.periodStartMinute, charged.accountingId, UUID.nameUUIDFromBytes("snooze:$postTime:$key".encodeToByteArray()).toString())
223	            } else null
224	            completion = Completion(key, charged, spend, nativeReturn = true)
225	            try {
226	                finishCompletion()
227	            } catch (cancelled: CancellationException) {
228	                throw cancelled
229	            } catch (_: Exception) {
230	                // The next gated operation resumes the steps that did not finish.
231	            }
232	            SnoozeReturnDecision.Charged
233	        }
234	    } catch (cancelled: CancellationException) {
235	        throw cancelled
236	    } catch (_: Exception) {
237	        if (completion?.let { it.nativeReturn && it.id == key } == true) SnoozeReturnDecision.Charged
238	        else SnoozeReturnDecision.NoFundedMoment
239	    }
240	
241	    suspend fun refreshSnoozeProxy(item: NotificationItem) = gate.run { postSafely(item, refresh = true) }
242	
243	    fun acceptSnoozeEvent(id: String, order: Long) = accept(id, order)
244	
245	    suspend fun withSnoozeAdmission(
246	        id: String,
247	        order: Long,
248	        block: suspend (List<NotificationItem>, DeliveryBudgetState) -> Boolean,
249	    ): Boolean = gate.run {
250	        val admitted = block(rows.liveSnoozes(), budget.read())
251	        if (admitted) acceptSnoozeEvent(id, order)
252	        admitted
253	    }
254	
255	    suspend fun onRemoved(id: String, reason: NotificationRemovalReason, atMillis: Long, eventOrder: Long? = null) {
256	        if (reason != NotificationRemovalReason.SOURCE_APP_CANCELLED && reason != NotificationRemovalReason.USER_DISMISSED && reason != NotificationRemovalReason.INBOX_CLEARED) return
257	        if (eventOrder == null) synchronized(this) {
258	            legacyRemovals[id] = maxOf(legacyRemovals[id] ?: Long.MIN_VALUE, atMillis)
259	            if (legacyRemovals.size > eventCapacity) legacyRemovals.remove(legacyRemovals.keys.first())
260	        }
261	        gate.run {
262	            if (eventOrder != null && synchronized(this) { (events[id]?.accepted ?: 0) > eventOrder }) return@run
263	            val current = rows.find(id)
264	            if (eventOrder == null && current != null && current.timestamp > atMillis) return@run
265	            rows.markCleared(id)
266	            if (eventOrder != null) removalApplied(id, eventOrder)
267	        }
268	    }
269	
270	    suspend fun clearInbox(id: String, delete: suspend () -> Unit) {
271	        val order = captureEvent(id, removed = true)
272	        gate.run { rows.markCleared(id); delete(); removalApplied(id, order) }
273	    }
274	    suspend fun clearAll(delete: suspend () -> Unit) {
275	        invalidateAll()
276	        gate.run { delete() }
277	    }
278	
279	    suspend fun onBatchTick(now: Instant = Instant.now()): List<DeliveryOutcome> = gate.run {
280	        val removals = synchronized(this) { events.filterValues { it.lastRemoval > it.accepted && it.appliedRemoval < it.lastRemoval }.map { it.key to it.value.lastRemoval } }
281	        removals.forEach { (id, order) -> rows.markCleared(id); removalApplied(id, order) }
282	        val settings = environment.settings()
283	        val time = environment.timeContext()
284	        val visibleSources = environment.activeSourceKeys()
285	        val tickInterval = time.boundaryIntervalMinutes * 60_000L
286	        val owned = rows.liveSnoozes().filter {
287	            val due = it.snoozeDeadline
288	            due != null && due <= now.toEpochMilli() && now.toEpochMilli() - due < tickInterval
289	        }
290	        val pending = rows.pending(NotificationPriority.LOW.level).filter {
291	            NotificationDeliveryPolicy.shouldDeliverOnBatchTick(it.priority, settings, time)
292	        }.toMutableList()
293	        val outcomes = mutableListOf<DeliveryOutcome>()
294	        while (pending.isNotEmpty() && outcomes.size < MAX_BATCH_ATTEMPTS) {
295	            val candidate = NotificationDeliveryPolicy.orderCandidates(pending, environment.queuePreferences()).first()
296	            pending.removeAll { it.id == candidate.id }
297	            val current = rows.find(candidate.id)
298	            val outcome = if (current == null || current.isCleared || explicitlyRemoved(candidate.id)) {
299	                rows.markCleared(candidate.id)
300	                DeliveryOutcome.Cleared(candidate.id)
301	            } else if (current.deliveryInvalidated || ambiguous(current)) {
302	                persistInvalidations()
303	                DeliveryOutcome.Invalidated(candidate.id)
304	            } else if (current.isDelivered || current.snoozeDeadline != null || bypassed(candidate.id) || candidate.id in visibleSources) DeliveryOutcome.Deferred(candidate.id)
305	            else deliver(current, owned)
306	            outcomes += outcome
307	            if (outcome is DeliveryOutcome.CommitPending) break
308	            if (outcome is DeliveryOutcome.Delivered) {
309	                rows.nextHead(candidate)?.let { next -> if (pending.none { it.id == next.id }) pending += next }
310	            }
311	        }
312	        outcomes
313	    }
314	
315	    private suspend fun deliver(item: NotificationItem, reserved: List<NotificationItem> = emptyList()): DeliveryOutcome {
316	        // Recheck callback-side tombstones at the effect boundary, even if removal work is queued.
317	        if (explicitlyRemoved(item.id) || rows.find(item.id)?.isCleared != false) {
318	            rows.markCleared(item.id)
319	            return DeliveryOutcome.Cleared(item.id)
320	        }
321	        if (item.deliveryInvalidated || ambiguous(item)) { persistInvalidations(); return DeliveryOutcome.Invalidated(item.id) }
322	        if (bypassed(item.id) || unprocessed(item.id)) return DeliveryOutcome.Deferred(item.id)
323	        val time = environment.timeContext()
324	        val schedule = environment.schedule()
325	        val setting = environment.settings()[item.priority] ?: PriorityDeliverySetting.defaultFor(item.priority)
326	        val decision = NotificationDeliveryPolicy.canDeliverNow(item.priority, setting, schedule, time, budget.read())
327	        if (setting.budgetBehavior == BudgetBehavior.RESPECTING && reserved.isNotEmpty()) {
328	            val points = reserved.sumOf { it.snoozePriority?.pointCost ?: 0 }
329	            val limit = NotificationDeliveryPolicy.findActivePeriod(schedule, time.scheduleMinuteOfDay)?.budgetPoints ?: 0
330	            if (decision.updatedBudget.spentPoints.toLong() + points + item.priority.pointCost > limit) return DeliveryOutcome.Deferred(item.id)
331	        }
332	        if (!decision.canDeliver) return DeliveryOutcome.Deferred(item.id)
333	        if (explicitlyRemoved(item.id) || rows.find(item.id)?.isCleared != false) {
334	            rows.markCleared(item.id)
335	            return DeliveryOutcome.Cleared(item.id)
336	        }
337	        if (ambiguous(item)) { persistInvalidations(); return DeliveryOutcome.Invalidated(item.id) }
338	        if (bypassed(item.id) || unprocessed(item.id)) return DeliveryOutcome.Deferred(item.id)
339	        return when (val post = postSafely(item)) {
340	            is PostResult.Failed -> DeliveryOutcome.PostFailed(item.id, post.reason)
341	            PostResult.Posted -> {
342	                val charged = NotificationDeliveryPolicy.recordPassthrough(item.priority, setting, schedule, time.scheduleMinuteOfDay, decision.updatedBudget)
343	                val entry = if (setting.budgetBehavior == ly.com.tahaben.notification_filter_domain.model.BudgetBehavior.RESPECTING && item.priority.pointCost > 0)
344	                    BudgetSpendEntry(item.appName.orEmpty(), item.title.orEmpty(), item.priority, item.priority.pointCost,
345	                        System.currentTimeMillis(), charged.periodStartMinute, charged.accountingId, java.util.UUID.randomUUID().toString()) else null
346	                // At most one unresolved effect is retained. All subsequent mutations recover it under this gate.
347	                completion = Completion(item.id, charged, entry)
348	                try { finishCompletion() }
349	                catch (cancelled: kotlinx.coroutines.CancellationException) { throw cancelled }
350	                catch (_: Exception) { return DeliveryOutcome.CommitPending(item.id) }
351	                DeliveryOutcome.Delivered(item.id)
352	            }
353	        }
354	    }
355	
356	    private suspend fun postSafely(item: NotificationItem, refresh: Boolean = false): PostResult = try {
357	        if (refresh) poster.refresh(item) else poster.post(item)
358	    } catch (cancelled: kotlinx.coroutines.CancellationException) {
359	        throw cancelled
360	    } catch (_: Exception) {
361	        PostResult.Failed("notification_post_failed")
362	    }
363	
364	    companion object { const val MAX_EVENT_KEYS = 4096; const val MAX_BATCH_ATTEMPTS = 256 }
365	}
